import os, pandas as pd;
workspace_data = os.environ.get('WORKSPACE_DATA');
path_bars = os.path.join(workspace_data, 'daily_bars', 'part-000.parquet');
df_bars = pd.read_parquet(path_bars);
wide_bars = df_bars.pivot(index='session_date', columns='asset_id', values='close');
last_day = wide_bars.iloc[-1];
previous_day = wide_bars.iloc[-2];
rets = (last_day - previous_day) / previous_day;
print(rets.sort_values(ascending=False).to_dict())
